package service
import("context";"path/filepath";"testing";"task133-structload/internal/clock";"task133-structload/internal/store")
func TestBug29_CombinationCreationRollsBackWhenAuditWriteFails(t *testing.T){st,e:=store.Open(filepath.Join(t.TempDir(),"c.db"));if e!=nil{t.Fatal(e)};defer st.Close();ctx:=context.Background();p,_:=New(st,clock.Real{}).CreateProject(ctx,CreateProjectInput{Code:"P",Name:"p",Exposure:"C",Importance:"II",WindSpeed:380});svc:=New(st,clock.Real{});st.DB().ExecContext(ctx,`CREATE TRIGGER reject_combo_event BEFORE INSERT ON event_log WHEN NEW.event_type='define_combination' BEGIN SELECT RAISE(ABORT,'blocked'); END`);if _,e=svc.CreateCombination(ctx,p.ID,CreateCombinationInput{Name:"bad",Kind:"strength",CoeffD:120});e==nil{t.Fatal("creation should fail")};cs,_:=svc.ListCombinations(ctx,p.ID);if len(cs)!=0{t.Fatalf("left combinations=%+v",cs)}}
